import {PROFILES,ARABIC_DEMO_MEALS,profileFor,profileName,newPatient,restorePatient,enableInitialReminders,patientSourceKey,clockDate,doseRows,dueRows,timingFor,compareBottle,compareTag,nfcTagFor,parseTag,saveBottleCheck,clearBottleCheck,bottleChecked,logTaken,skipDose,syncMissed,setClock,addCaregiver,removeCaregiver,applyEhrChange,ehrBundle,labsFromEhr} from './next-core.mjs';
