const $=s=>document.querySelector(s),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const states=new Map();let activeId=null,view='now',subview='medicines',loginLanguage='en',dialogType='',activeDoseKey='',scanVersion=0,scanBusy=false,ocrResult=null,ocrText='',ocrConfidence=0,scanMethod='',imageUrl='',nfcAbort=null,nfcWaiting=false,nfcNote='',writeAbort=null,photoRecords=[],photoUrls=[],voiceStatus='',careView=false,ask={medId:'',text:'',sampleId:null,result:null};
try{activeId=sessionStorage.getItem('dawa-next-active');if(!profileFor(activeId))activeId=null;}catch{}
function loadPatient(id){if(states.has(id))return states.get(id);let saved;try{saved=JSON.parse(localStorage.getItem(patientSourceKey(id)));}catch{}const next=saved?restorePatient(saved,id):enableInitialReminders(newPatient(id));states.set(id,next);return next;}
const p=()=>activeId?loadPatient(activeId):null;
const lang=()=>careView&&p()?.caregiver?p().caregiver.language:p()?.patientLang||loginLanguage;
const t=en=>textFor(en,lang());
function store(next){if(!next||next.id!==activeId)return;states.set(activeId,next);try{localStorage.setItem(patientSourceKey(activeId),JSON.stringify(next));}catch{toast(t('This browser cannot retain changes after reload.'));}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const paths={now:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',meds:'<path d="m9 5 10 10M5 19a6 6 0 0 1 0-8l6-6a6 6 0 0 1 8 8l-6 6a6 6 0 0 1-8 0Z"/>',food:'<path d="M5 3v7m3-7v7m-6-7v7c0 3 6 3 6 0M5 13v8M18 3c-5 5-4 9 0 9V3m0 9v9"/>',me:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',sound:'<path d="M3 9h4l5-5v16l-5-5H3zM16 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',camera:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="m8 6 2-3h4l2 3"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',nfc:'<path d="M5 7c4 3 4 7 0 10m5-13c7 5 7 11 0 16m6-18c9 6 9 14 0 20"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM9 21h6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',ask:'<path d="M4 5h16v11H9l-5 4z"/><path d="M8 9.5h8M8 12.5h5"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.meds}</svg>`;
const name=m=>MED_LANG[m.id]?.[lang()+'Name']||m.name;
const local=o=>o?.[lang()]||o?.en||'';
const directions=m=>translatedDirection(m,lang());
const strength=m=>lang()==='ar'?m.strength.replace('mg','ملغ').replace('IU','وحدة دولية'):lang()==='ru'?m.strength.replace('mg','мг').replace('IU','МЕ'):m.strength;
const patientName=()=>profileName(profileFor(activeId),lang());
const foodName=e=>e.demoMealId?(local(ARABIC_DEMO_MEALS.find(m=>m.id===e.demoMealId))||e.label):e.foodId?(local(DEMO_FOODS.find(f=>f.id===e.foodId))||e.label):e.label;
const statusLabel={due:'Due now',early:'Upcoming',late:'Not logged',taken:'Taken',skipped:'Skipped',review:'Review first',unknown:'Review first'};
const medVisual=m=>`<span class="med-symbol ${esc(m.color)}">${icon('meds')}</span>`;
const sourceButton=key=>`<button class="source-button" data-source="${key}">${t('Why?')} ↗</button>`;
function header(){return `<header><a class="brand" href="#" aria-label="dawa."><img src="./brand/dawa-logo.png" alt="dawa." width="100" height="50"></a><div class="header-actions">${activeId?`<button class="icon-button" data-action="accessibility" aria-label="${t('Accessibility')}">${icon('me')}</button>`:''}<label class="language"><span class="sr-only">${t('Display language')}</span><select id="language" aria-label="${t('Display language')}">${LANGUAGES.map(l=>`<option value="${l.code}" lang="${l.code}" ${lang()===l.code?'selected':''}>${l.label}</option>`).join('')}</select></label></div></header>`;}
function render(){document.documentElement.lang=lang();document.documentElement.dir=languageInfo(lang()).dir;const state=p();if(state){document.body.dataset.textSize=state.accessibility.textSize||'standard';document.body.dataset.contrast=state.accessibility.highContrast?'high':'normal';document.body.dataset.motion=state.accessibility.reduceMotion?'reduce':'normal';setVoiceRate(state.accessibility.speechRate||1);}else document.body.dataset.textSize='standard';
 $('#app').innerHTML=`<div class="app-shell">${header()}<main id="main-content">${!state?loginView():careView?caregiverPage():`<div class="page-heading"><div><small>${t('Hello')}, ${esc(patientName())}</small><h1>${t({now:'Take Now',meds:'My medicines',food:'Food & nutrition',ask:'Ask Dawa',me:'Me'}[view])}</h1></div>${view==='now'?`<button class="clock-chip" data-action="clock"><span>${t(state.liveClock?'Use device time':'Demo time')}</span><b dir="ltr">${clockDate(state).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</b></button>`:''}</div>${view==='now'?nowView():view==='meds'?medsView():view==='food'?foodView():view==='ask'?askView():meView()}` }<p class="safety-line">${t('Sample data only. Not medical advice.')}</p></main>${state&&!careView?`<nav class="bottom-nav" aria-label="${t('Main navigation')}">${[['now','now','Take Now'],['meds','meds','My medicines'],['food','food','Food & nutrition'],['ask','ask','Ask Dawa'],['me','me','Me']].map(([v,i,label])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t(label)}</span></button>`).join('')}</nav>`:''}</div>`;
}
function loginView(){return `<section class="login-intro"><span class="eyebrow">${t('Take Now demo')}</span><h1>${t('Choose a demo patient')}</h1><p>${t(PROFILES.length===3?'Three sample patients. No password needed.':'Two sample patients. No password needed.')}</p></section><div class="patient-options">${PROFILES.map(profile=>`<button class="patient-login ${profile.id}" data-login="${profile.id}"><span class="avatar">${profile.initials}</span><span><strong>${esc(profileName(profile,lang()))}</strong><small>${profile.language==='en'?'English':`<span lang="${profile.language}">${languageInfo(profile.language).label}</span> · ${languageInfo(profile.language).english}`}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="login-footnote">${icon('check')}<p>${t('5 medicines from the sample EHR')}</p></div>`;}
function nowView(){const rows=doseRows(p()),due=dueRows(p()),next=rows.find(r=>timingFor(r,p())==='early'),logged=rows.filter(r=>r.checked).length;return `<section class="take-hero"><div class="hero-mark">${icon('now')}</div><small>${t('Ready when you are')}</small><h2>${due.length?`<b>${due.length}</b> ${t('medicines due now')}`:t('No medicines due now')}</h2>${due.length?`<p>${due.map(r=>esc(name(r.med))).join(' · ')}</p><button class="primary light full" data-action="start">${t('Start check-in')}${icon('arrow')}</button>`:next?`<div class="next-row"><span>${t('Next')}: ${esc(name(next.med))}</span><b dir="ltr">${next.time}</b></div>`:''}</section><div class="today-progress"><b>${logged}/${rows.filter(r=>!r.needsReview).length}</b><span>${t('logged today')}</span></div><button class="wide-link" data-action="schedule">${icon('now')}${t('See today’s schedule')}${icon('arrow')}</button>${p().caregiver?`<button class="wide-link" data-action="caregiver">${icon('bell')}${t('Caregiver inbox')}<b>${p().alerts.filter(a=>!a.read).length}</b></button>`:''}<details class="schedule-inline"><summary>${t('Today’s schedule')}</summary>${scheduleRows()}</details>`;}
function scheduleRows(){return doseRows(p()).map(r=>`<button class="schedule-row ${timingFor(r,p())}" data-dose="${esc(r.key)}"><time dir="ltr">${r.time||'—'}</time><span><b>${esc(name(r.med))}</b><small>${esc(strength(r.med))} · ${t(statusLabel[timingFor(r,p())])}</small></span>${r.checked?icon('check'):icon('arrow')}</button>`).join('');}
function warnings(m){const w=medicineWarnings(m.id);return `<section class="warnings"><div class="avoid ${w.avoid.length?'red':'neutral'}"><h3>${t('DO NOT take with')}</h3>${w.avoid.length?`<ul>${w.avoid.map(n=>`<li>${t(n.label)} ${sourceButton(n.source)}</li>`).join('')}</ul>`:`<p>${w.reviewed?t(w.noAvoid):t('Ask your pharmacist to check this medicine.')}</p>${w.source?sourceButton(w.source):''}`}</div>${w.checkFirst.length?`<details class="caution"><summary>${t('Check first')}</summary>${w.checkFirst.map(n=>`<p><b>${t(n.label)}</b><br>${t(n.note)} ${sourceButton(n.source)}</p>`).join('')}</details>`:''}</section>`;}
function medCard(m){const count=supplyFor(p(),m.id);return `<article class="medicine-card"><div class="med-head">${medVisual(m)}<div><h2>${esc(name(m))}</h2><p class="strength">${esc(strength(m))}</p></div></div><p class="directions">${esc(directions(m))}</p><div class="button-row"><button class="listen" data-listen="${m.id}">${icon('sound')}${t('Listen')}</button><button class="secondary" data-med="${m.id}">${t('Details')}</button></div><div class="supply"><b>${t('Pills left')}: ${count.count??t('Not available')}</b><small>${t('From your health record')}</small>${refillDue(p(),m.id)?`<span class="badge yellow">${t('Time to refill')}</span>`:''}</div>${getAdvisories(p()).filter(a=>a.id==='gelatin'&&m.id==='gabapentin').map(a=>`<div class="caution open"><b>${t(a.enTitle)}</b><p>${t(a.en)}</p>${sourceButton(a.source)}</div>`).join('')}${warnings(m)}</article>`;}
function medsView(){return `<div class="segment" role="group" aria-label="${t('Medicines and supplements')}"><button data-subview="medicines" class="${subview==='medicines'?'selected':''}" aria-pressed="${subview==='medicines'}">${t('Medicines')}</button><button data-subview="supplements" class="${subview==='supplements'?'selected':''}" aria-pressed="${subview==='supplements'}">${t('Supplements')}</button></div>${subview==='medicines'?p().meds.map(medCard).join(''):supplementsView()}`;}
function supplementsView(){return `<section class="card"><h2>${t('Vitamins and supplements')}</h2><p>${t('Add vitamins, herbs or teas you use. Include the ingredients and amount.')}</p><details><summary>${t('Add a vitamin or supplement')}</summary><label for="supplement-name">${t('Product name')}</label><input id="supplement-name" maxlength="80"><label for="supplement-ingredients">${t('Ingredients from the label')}</label><textarea id="supplement-ingredients" rows="2" maxlength="500"></textarea><button class="primary full" data-action="add-supplement">${t('Add to my shared list')}</button></details></section>${p().supplements.map(item=>`<section class="card"><span class="badge">${t('PATIENT-REPORTED')}</span><h2>${esc(item.name)}</h2><p>${esc(item.ingredients)}</p>${supplementReview(p(),item).map(n=>`<div class="caution open"><h3>${t(n.title)}</h3><p>${t(n.text)}</p>${sourceButton(n.source)}</div>`).join('')}<button class="text-button" data-remove-supplement="${item.id}">${t('Remove')}</button></section>`).join('')}<p class="note">${t('Adding a product is not a recommendation to take it. Do not start, stop, or change medicines or supplements based on this demo.')}</p>`;}
function foodView(){const labs=labsFromEhr(ehrBundle(p()));return `<section class="card food-search"><h2>${t('Food choices')}</h2><p class="note">${t('Add foods you eat. Remove any you do not want.')}</p><label for="food-choice">${t('Choose a food')}</label><select id="food-choice">${foodChoices(activeId).map(entry=>`<option value="${entry.id}">${esc(local(entry))}</option>`).join('')}</select><button class="primary full" data-action="add-food">${t('Add food')}</button><div class="traffic-legend"><span class="green">${t('Checked instruction')}</span><span class="yellow">${t('Check first')}</span><span class="red">${t('Avoid warning')}</span></div><p class="note">${t('Green applies only to the named check. Recipes may need ingredient review.')}</p><div id="food-results" aria-live="polite">${foodListResults()}</div></section><h2 class="section-heading">${t('Nutrition')}</h2><section class="card"><div class="section-title"><h2>${t('Lab results')}</h2><span class="badge">${t('From your health record')}</span></div><div class="lab-grid">${labs.map(l=>`<article class="lab ${l.flag==='N'?'normal':'abnormal'}"><div><h3>${t(l.name)}</h3><span class="lab-flag">${t(l.flag==='H'?'High':l.flag==='L'?'Low':'Normal')}</span></div><p><strong>${l.value}</strong> <bdi>${l.unit}</bdi></p><small>${t('Reference range')}: <bdi>${t(l.range)}</bdi></small><small>${t('Flag from EHR')} · ${new Date(l.date).toLocaleDateString(languageInfo(lang()).locale)}</small></article>`).join('')}</div><p class="note">${t('Your lab flags come from the sample health record. They are not a new diagnosis.')}</p></section>${p().useEhrHealth&&labs.some(l=>l.name==='LDL cholesterol'&&l.flag==='H')?`<section class="nutrition-card"><span class="eyebrow">${t('Food ideas from your record')}</span><h2>${t('Your record flags high LDL cholesterol.')}</h2><p>${t('Try oats, beans or lentils. Use less butter and fatty meat.')}</p><p class="note">${t('These are food ideas, not a treatment plan.')}</p>${sourceButton('cholesterol')}</section>`:''}`;}
function meView(){return `<section class="card profile"><span class="avatar">${profileFor(activeId).initials}</span><div><h2>${esc(patientName())}</h2><p>${t('Age')} ${profileFor(activeId).age} · ${t('Demo login')}</p></div></section><section class="card"><h2>${t('New medicine photos')}</h2><p>${t('Upload a bottle label for pharmacist review. This does not add a prescription.')}</p><label for="photo-label">${t('Photo label')}</label><input id="photo-label" maxlength="100" placeholder="${t('For example: new bottle from pharmacy')}"><label class="primary full file-label">${icon('camera')}${t('Add a medicine photo')}<input type="file" id="new-photo" accept="image/jpeg,image/png,image/webp" capture="environment"></label><p class="note">${t('Reading labels runs on this device. Photos are not uploaded.')}</p><div class="photo-list">${photoRecords.length?photoRecords.map(record=>`<article class="review-photo"><img src="${record.url}" alt="${esc(record.label||t('For pharmacist review'))}"><div><b>${esc(record.label||t('For pharmacist review'))}</b><span class="badge yellow">${t('For pharmacist review')}</span><details><summary>${t('Label text')}</summary><p class="ocr-text" dir="ltr">${esc(record.text||t('Could not read the label clearly.'))}</p></details><button class="text-button" data-delete-photo="${record.id}">${t('Remove photo')}</button></div></article>`).join(''):`<p class="note">${t('No medicine photos yet')}</p>`}</div></section><section class="card settings-list"><h2>${t('Settings')}</h2><label class="toggle"><span><b>${t('Require bottle check')}</b><small>${t('Check a bottle or tag before “I took it”.')}</small></span><input type="checkbox" id="require-bottle" ${p().requireBottle?'checked':''}></label><p class="note">${t('Turning this off does not change the time check.')}</p><label class="toggle"><span>${t('Use lab results for food ideas')}</span><input type="checkbox" id="use-labs" ${p().useEhrHealth?'checked':''}></label><label class="toggle"><span>${t('Avoid pork-derived gelatin')}</span><input type="checkbox" id="avoid-pork" ${p().avoidPork?'checked':''}></label><p class="note">${t('This is your own choice. We do not infer it from your language.')}</p><button class="wide-link" data-action="accessibility">${t('Accessibility')}${icon('arrow')}</button></section>${caregiverSettings()}<section class="card"><h2>${t('Demo controls')}</h2><button class="secondary full" data-action="clock">${t('Set demo time')}</button><button class="secondary full" data-action="ehr">${t('Sample health record')}</button><button class="text-button full" data-action="reset">${t('Reset this patient')}</button><button class="text-button full" data-action="logout">${t('Switch patient')}</button></section>`;}
function caregiverSettings(){return `<section class="card"><h2>${t('Caregiver')}</h2><label for="caregiver-name">${t('Caregiver name')}</label><input id="caregiver-name" maxlength="60" value="${esc(p().caregiver?.name||'')}"><label for="caregiver-lang">${t('Preferred language')}</label><select id="caregiver-lang">${LANGUAGES.map(l=>`<option value="${l.code}" lang="${l.code}" ${(p().caregiver?.language||'en')===l.code?'selected':''}>${l.label}</option>`).join('')}</select><label class="toggle"><span>${t('Alert for missed or skipped doses')}</span><input id="caregiver-notify" type="checkbox" ${p().caregiver?.notify!==false?'checked':''}></label><button class="primary full" data-action="save-caregiver">${t('Save caregiver')}</button>${p().caregiver?`<button class="secondary full" data-action="caregiver">${t('Open caregiver demo')} · ${p().alerts.filter(a=>!a.read).length}</button><button class="text-button full" data-action="remove-caregiver">${t('Remove caregiver')}</button>`:''}<p class="note">${t('In-demo alerts only. No text, email or push is sent.')}</p></section>`;}
function caregiverPage(){if(!p().caregiver)return `<h1>${t('No caregiver added')}</h1><button class="primary full" data-action="patient">${t('Back to patient')}</button>`;return `<div class="page-heading"><div><small>${esc(p().caregiver.name)}</small><h1>${t('Caregiver inbox')}</h1></div></div><p class="note">${t('In-demo alerts only. No text, email or push is sent.')}</p>${p().alerts.length?p().alerts.map(a=>{const m=p().meds.find(m=>m.id===a.medId);return `<article class="alert-card ${a.read?'read':''}"><span class="badge ${a.kind==='skipped'?'yellow':''}">${t(a.kind==='skipped'?'Dose was skipped':'Dose has not been logged')}</span><h2>${esc(m?name(m):a.medId)}</h2><p><bdi>${a.time}</bdi> · ${esc(patientName())}</p><small>${t('An unlogged dose does not prove it was missed.')}</small></article>`;}).join(''):`<section class="card empty"><h2>${t('No alerts yet')}</h2>${icon('check')}</section>`}<button class="secondary full" data-action="read-alerts">${t('Mark all read')}</button><button class="primary full" data-action="patient">${t('Back to patient')}</button>`;}
let queueKeys=[],queueIndex=0;
function closeDialog(){scanVersion++;scanBusy=false;nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;nfcNote='';writeAbort?.abort();writeAbort=null;cancelRecording();stopVoice();if($('#dialog').open)$('#dialog').close();dialogType='';activeDoseKey='';queueKeys=[];if(imageUrl.startsWith('blob:'))URL.revokeObjectURL(imageUrl);imageUrl='';}
function showDialog(content,kind){dialogType=kind;$('#dialog').innerHTML=`<button class="close-button" data-action="close" aria-label="${t('Close')}">${icon('close')}</button>${content}`;if(!$('#dialog').open)$('#dialog').showModal();}
function startQueue(){queueKeys=dueRows(p()).map(r=>r.key);queueIndex=0;if(!queueKeys.length){showDialog(`<h2>${t('No medicines due now')}</h2><button class="primary full" data-action="close">${t('Continue')}</button>`,'done');return;}openDose(queueKeys[0],true);}
function openDose(key,keepQueue=false){const row=doseRows(p()).find(r=>r.key===key);if(!row)return;if(!keepQueue){queueKeys=[];queueIndex=0;}scanVersion++;scanBusy=false;nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;nfcNote='';activeDoseKey=key;ocrResult=null;ocrText='';ocrConfidence=0;scanMethod='';imageUrl='';renderDose();}
function renderDose(){const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(!row)return closeDialog();const status=timingFor(row,p()),checked=bottleChecked(p(),row),canLog=status==='due'&&(!p().requireBottle||checked),end=String(Math.floor((Number(row.time.slice(0,2))*60+Number(row.time.slice(3))+30)/60)).padStart(2,'0')+':'+String((Number(row.time.slice(3))+30)%60).padStart(2,'0');
 showDialog(`<div class="dose-step"><span>${queueKeys.length?t('Dose')+' '+(queueIndex+1)+' '+t('of')+' '+queueKeys.length:t('Check bottle')}</span><b dir="ltr">${row.time||'—'}</b></div><div class="med-head modal-med">${medVisual(row.med)}<div><h2>${esc(name(row.med))}</h2><p class="strength">${esc(strength(row.med))}</p></div></div><p class="directions">${esc(directions(row.med))}</p><button class="listen full" data-listen="${row.med.id}">${icon('sound')}${t('Listen')}</button>${status==='due'?`<p class="badge positive">${t('Due now')}</p>`:status==='early'||status==='late'?`<div class="time-block"><h3>${t('Do not take yet')}</h3><p>${status==='early'?t('Your next time is')+' '+row.time:t('This time has passed. Ask your care team what to do.')}</p></div>`:`<div class="time-block"><h3>${t(statusLabel[status])}</h3>${status==='review'?`<p>${t('New medicine needs pharmacist review before dose check-in.')}</p>`:''}</div>`}<small class="note">${t('Demo check-in window')}: <bdi>${row.time||'—'}–${row.time?end:'—'}</bdi><br>${t('Demo timing check only. Follow your doctor’s directions.')}</small>${['taken','skipped','review'].includes(status)?'':`<section class="bottle-check"><div class="section-title"><h3>${t('Check bottle')}</h3>${checked?`<span class="badge positive">${icon('check')}${t('Ready')}</span>`:''}</div><div class="scan-options"><label class="secondary file-label ${scanBusy?'disabled':''}">${icon('camera')}${t('Scan bottle photo')}<input type="file" id="bottle-photo" accept="image/jpeg,image/png,image/webp" capture="environment" ${scanBusy?'disabled':''}></label><button class="secondary" data-action="nfc" ${scanBusy?'disabled':''}>${icon('nfc')}${t('Tap NFC tag')}</button></div><div class="sample-actions"><button class="text-button" data-action="sample-ocr" ${scanBusy?'disabled':''}>${t('Try sample bottle')}</button><button class="text-button" data-action="wrong-ocr" ${scanBusy?'disabled':''}>${t('Try wrong bottle')}</button><button class="text-button" data-action="demo-tag" ${scanBusy?'disabled':''}>${t('Demo NFC tag')}</button><button class="text-button" data-action="wrong-tag" ${scanBusy?'disabled':''}>${t('Wrong demo tag')}</button></div><p class="note">${t('Sample bottles use English label text. The result is explained in your language.')}</p>${imageUrl?`<img class="scan-image" src="${imageUrl}" alt="${t('Demo label, not a real prescription')}">`:''}<div id="scan-status" role="status" class="scan-status ${nfcWaiting?'waiting':nfcNote?'unclear':ocrResult?.status||''}">${nfcWaiting?`<b>${icon('nfc')}${t('Waiting for the tag…')}</b><p>${t('Hold the top of your phone’s back against the tag on the bottle.')}</p><button class="text-button" data-action="nfc-cancel">${t('Cancel')}</button>`:nfcNote?`<b>${t(nfcNote)}</b>`:scanBusy?t('Reading the label…'):ocrResult?`${scanMethod==='demo-nfc'?`<small>${t('Demo NFC tag')}</small><br>`:''}<b>${t(ocrResult.reason)}${ocrResult.otherMedId?' '+esc(name(p().meds.find(m=>m.id===ocrResult.otherMedId)||{id:ocrResult.otherMedId,name:ocrResult.otherMedId})):''}</b><p>${t(ocrResult.status==='matched'?(scanMethod.includes('nfc')?'Tag match only. Check that the tag is on the right bottle.':'Label match only. This does not confirm the bottle’s contents.'):scanMethod.includes('nfc')?'Check that you picked up the right bottle.':'Check the label with your pharmacist.')}</p>${ocrResult.status!=='matched'&&scanMethod==='nfc'&&nfcSupported()?`<button class="text-button" data-write-tag="${row.med.id}">${t('Program this bottle’s tag')}</button>`:''}`:''}</div>${ocrText?`<details class="ocr-details"><summary>${t('OCR result')} · ${Math.round(ocrConfidence)}%</summary><p class="ocr-text" dir="ltr">${esc(ocrText)}</p></details>`:''}<p class="note">${p().requireBottle?t('Check the bottle, then log your dose.'):t('Bottle check is optional')}</p></section><button class="primary full" data-action="record-dose" ${canLog&&!scanBusy?'':'disabled'}>${status==='early'||status==='late'?t('Do not take yet'):t('I took it')}</button>${!checked&&p().requireBottle?`<p class="note centered">${t('Check the bottle first')}</p>`:''}<button class="text-button full" data-action="skip-dose">${t('Skip this dose')}</button><p class="note">${t('This is your own dose report. The app cannot confirm you swallowed it.')}</p>`}<details class="dose-food"><summary>${t('Food and drink warnings')}</summary>${warnings(row.med)}</details><button class="text-button full" data-action="schedule">${t('See today’s schedule')}</button>`,'dose');
}
function afterDose(lastAction='taken'){queueIndex++;while(queueIndex<queueKeys.length){const next=doseRows(p()).find(r=>r.key===queueKeys[queueIndex]);if(next&&timingFor(next,p())==='due'){openDose(next.key,true);render();return;}queueIndex++;}activeDoseKey='';queueKeys=[];scanVersion++;render();showDialog(`<div class="done-mark">${icon('check')}</div><h2>${t('All done for now')}</h2><p>${t(lastAction==='skipped'?'Dose skipped in this demo.':'Your dose was logged.')}</p><button class="primary full" data-action="close">${t('Continue')}</button>`,'done');}
async function scanBottle(input,isSample=false){const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(!row||scanBusy)return;const patientId=activeId,key=activeDoseKey,version=++scanVersion;
 if(!isSample){if(!['image/jpeg','image/png','image/webp'].includes(input?.type)||!input.size||input.size>5*1024*1024){toast(t('Use a JPG, PNG or WebP under 5 MB.'));return;}try{const bitmap=await createImageBitmap(input);bitmap.close();}catch{toast(t('OCR could not read this image. Try another clear photo.'));return;}}
 if(version!==scanVersion||activeId!==patientId||activeDoseKey!==key)return;store(clearBottleCheck(p(),key));if(imageUrl.startsWith('blob:'))URL.revokeObjectURL(imageUrl);imageUrl=isSample?input:URL.createObjectURL(input);nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;nfcNote='';scanBusy=true;ocrResult=null;ocrText='';scanMethod='ocr';renderDose();
 try{const result=await readBottleText(input,progress=>{if(version!==scanVersion||activeId!==patientId||dialogType!=='dose')return;const el=$('#scan-status');if(el)el.textContent=t('Reading the label…')+' '+Math.round(progress.progress*100)+'%';});if(version!==scanVersion||activeId!==patientId||activeDoseKey!==key)return;
  ocrText=result.text;ocrConfidence=result.confidence;ocrResult=compareBottle(row.med,result);if(ocrResult.status==='matched')store(saveBottleCheck(p(),key,ocrResult,'ocr'));
 }catch{if(version!==scanVersion||activeId!==patientId)return;ocrResult={status:'unclear',reason:'OCR could not read this image. Try another clear photo.'};}
 finally{if(version===scanVersion&&activeId===patientId){scanBusy=false;renderDose();}}
}
function tagResult(payload,method){const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(!row)return;nfcWaiting=false;nfcNote='';store(clearBottleCheck(p(),row.key));ocrResult=compareTag(p(),row.med,payload);scanMethod=method;ocrText='';imageUrl='';if(ocrResult.status==='matched')store(saveBottleCheck(p(),row.key,ocrResult,method));renderDose();}
// Read a bottle tag (Chrome on Android only). The dialog shows a waiting state until a tag is tapped or the user cancels.
async function scanNfc(){
 if(!nfcSupported()){nfcAbort=null;nfcWaiting=false;nfcNote=unsupportedMessage();ocrResult=null;renderDose();return;}
 const patientId=activeId,key=activeDoseKey,version=++scanVersion,current=()=>activeId===patientId&&activeDoseKey===key&&version===scanVersion;
 nfcAbort?.abort();writeAbort?.abort();writeAbort=null;const controller=new AbortController();nfcAbort=controller;
 nfcNote='';ocrResult=null;ocrText='';imageUrl='';scanMethod='nfc';nfcWaiting=true;renderDose();
 try{await startTagScan({signal:controller.signal,
  onPayload:payload=>{if(!current())return;controller.abort();if(nfcAbort===controller)nfcAbort=null;tagResult(payload,'nfc');},
  onError:message=>{if(!current())return;nfcWaiting=false;nfcNote=message;renderDose();}});}
 catch(error){if(!current())return;if(nfcAbort===controller)nfcAbort=null;nfcWaiting=false;nfcNote=nfcErrorMessage(error)||'';renderDose();}
}
// Program a blank sticker with this medicine's tag (URL record + text record).
async function writeTag(medId){
 const m=p()?.meds.find(m=>m.id===medId);if(!m)return;
 if(!nfcSupported()){toast(t(unsupportedMessage()));return;}
 nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;writeAbort?.abort();const controller=new AbortController();writeAbort=controller;
 const say=message=>{const el=$('#tag-write-status');if(el)el.textContent=message;toast(message);};
 say(t('Hold a blank NFC sticker against the back of your phone.'));
 try{await writeBottleTag(nfcTagFor(p(),m),{signal:controller.signal});say(t('Tag written. Stick it on this medicine’s bottle.'));}
 catch(error){const message=nfcErrorMessage(error,'write');if(message)say(t(message));}
 finally{if(writeAbort===controller)writeAbort=null;}
}
// A programmed tag tapped while the app is closed opens …/#tag=<payload>. Jump to that medicine's due dose and check it.
async function handleTagLink(){
 const payload=payloadFromHash(location.hash);if(!payload)return;
 try{history.replaceState(null,'',location.pathname+location.search);}catch{}
 const tag=parseTag(payload);
 if(!tag||!profileFor(tag.patientId)){toast(t('This is not a dawa bottle tag. Program it from this medicine’s details first.'));return;}
 if(activeId&&activeId!==tag.patientId){toast(t('This tag belongs to another patient.'));return;}
 if(!activeId)await login(tag.patientId);
 const med=p().meds.find(m=>m.id===tag.medId);if(!med){toast(t('This tag does not match this prescription.'));return;}
 const row=dueRows(p()).find(r=>r.med.id===med.id);
 if(!row){toast(name(med)+': '+t('This medicine is not due now.'));return;}
 closeDialog();openDose(row.key);tagResult(payload,'nfc');toast(t('Bottle tag tapped:')+' '+name(med));
}
function showSource(key){const source={...SOURCES,...FOOD_CHECK_SOURCES,...ASK_SOURCES}[key];if(!source)return;showDialog(`<span class="eyebrow">${t('Sources')}</span><h2>${esc(source.title)}</h2><p>${t('Source links open the original publication.')}</p><a class="primary full" href="${source.url}" target="_blank" rel="noopener noreferrer">${t('Read guide')} ↗</a>`,'source');}
function showSchedule(){activeDoseKey='';scanVersion++;showDialog(`<h2>${t('Today’s schedule')}</h2><p class="note">${t('Demo time')}: <bdi>${p().clock}</bdi></p>${scheduleRows()}`,'schedule');}
function showClock(){showDialog(`<h2>${t('Set demo time')}</h2><p class="note">${t('Demo timing check only. Follow your doctor’s directions.')}</p><label for="demo-clock">${t('Demo time')}</label><input type="time" id="demo-clock" value="${p().clock}"><button class="primary full" data-action="save-clock">${t('Save')}</button><div class="clock-examples">${[['07:00','Wrong-time example'],['08:00','Morning'],['09:00','Missed-dose example'],['18:00','Evening']].map(([time,label])=>`<button class="secondary" data-clock="${time}"><bdi>${time}</bdi>${t(label)}</button>`).join('')}</div><label class="toggle"><span>${t('Use device time')}</span><input type="checkbox" id="live-clock" ${p().liveClock?'checked':''}></label>`,'clock');}
function showAccess(){showDialog(`<h2>${t('Accessibility')}</h2><label for="text-size">${t('Text size')}</label><select id="text-size">${[['standard','Standard'],['large','Large'],['extra','Extra large'],['largest','Largest']].map(([v,label])=>`<option value="${v}" ${p().accessibility.textSize===v?'selected':''}>${t(label)}</option>`).join('')}</select><label for="speech-rate">${t('Speech speed')}</label><select id="speech-rate">${[[.75,'Slower'],[1,'Normal'],[1.25,'Faster']].map(([v,label])=>`<option value="${v}" ${(p().accessibility.speechRate||1)===v?'selected':''}>${t(label)}</option>`).join('')}</select>${[['highContrast','High contrast'],['reduceMotion','Less movement'],['quiet','Quiet reminders']].map(([key,label])=>`<label class="toggle"><span>${t(label)}</span><input type="checkbox" data-access="${key}" ${p().accessibility[key]?'checked':''}></label>`).join('')}<button class="secondary full" data-action="stop-audio">${t('Stop reading aloud')}</button>`,'access');}
function showMed(id){const m=p().meds.find(m=>m.id===id);if(!m)return;const supply=supplyFor(p(),id);showDialog(`<div class="med-head">${medVisual(m)}<div><h2>${esc(name(m))}</h2><p>${esc(strength(m))}</p></div></div><p class="directions">${esc(directions(m))}</p><details><summary>${t('Original directions')} · English</summary><p dir="ltr" lang="en">${esc(m.original)}</p></details>${warnings(m)}<h3 class="section-heading">${t('Dose reminders')}</h3>${doseRows(p()).filter(r=>r.med.id===id).map(r=>`<label class="toggle"><span><bdi>${r.time||'—'}</bdi><small>${t('From prescription')}</small></span><input type="checkbox" data-reminder="${m.id}|${r.slot}" ${r.reminderEnabled?'checked':''} ${r.needsReview?'disabled':''}></label>`).join('')}<h3 class="section-heading">${t('Pills and refills')}</h3><p><b>${t('Pills left')}: ${supply.count??t('Not available')}</b></p><p class="note">${t('Last saved count. Your count at home may be different.')}</p><label for="refill-threshold">${t('Remind me when this many are left')}</label><input type="number" id="refill-threshold" min="0" max="100000" value="${supply.refillAt}"><label for="package-expiry">${t('Expiration date (optional)')}</label><input type="date" id="package-expiry" value="${supply.expiresOn}"><button class="primary full" data-save-supply="${id}">${t('Save reminder')}</button><h3 class="section-heading">${icon('nfc')}${t('Bottle tag (NFC)')}</h3><p class="note">${t('Program a blank NFC sticker once. After that, tap the bottle to check it before each dose.')}</p><code class="tag-text" dir="ltr" translate="no">${esc(nfcTagFor(p(),m))}</code><div class="button-row">${nfcSupported()?`<button class="primary" data-write-tag="${m.id}">${icon('nfc')}${t('Write to NFC tag')}</button>`:''}<button class="secondary" data-copy-tag="${m.id}">${t('Copy tag text')}</button></div><p id="tag-write-status" class="note" role="status" aria-live="polite"></p><p class="note">${t(nfcSupported()?'You can also write this text with any NFC app as a plain text record.':'Writing and reading tags works in Chrome on Android. iPhone browsers cannot use NFC; use a bottle photo instead.')}</p>`,'med');}
function showEhr(){showDialog(`<h2>${t('Sample health record')}</h2><p class="note">${t('Sample data only. Not medical advice.')}</p><button class="secondary full" data-ehr-action="metformin">${t('Update metformin directions')}</button><button class="secondary full" data-ehr-action="gabapentin">${t('Add gabapentin 100 mg')}</button><p class="note">${t('No new dose is added automatically.')}</p><button class="text-button full" data-action="export">${t('Export sample record')}</button>`,'ehr');}
async function refreshPhotos(){for(const url of photoUrls)URL.revokeObjectURL(url);photoUrls=[];const id=activeId;if(!id){photoRecords=[];return;}try{const data=await patientPhotos(id);if(activeId!==id)return;photoRecords=data.map(record=>{const url=URL.createObjectURL(record.blob);photoUrls.push(url);return {...record,url};});}catch{photoRecords=[];} }
async function addPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file?.type)||!file.size||file.size>5*1024*1024){toast(t('Use a JPG, PNG or WebP under 5 MB.'));return;}const patientId=activeId,label=$('#photo-label')?.value||'';let text='',failed=false;toast(t('Reading the label…'));try{const result=await readBottleText(file);text=result.text;}catch{failed=true;}if(activeId!==patientId)return;try{await saveReviewPhoto(patientId,file,text,label);await refreshPhotos();render();toast(t(failed?'Photo saved. OCR was unavailable; the label still needs review.':'Photo saved for review.'));}catch(error){toast(t(error.message));}}

async function login(id){closeDialog();ask={medId:'',text:'',sampleId:null,result:null};activeId=id;careView=false;view='now';subview='medicines';store(syncMissed({...loadPatient(id),patientLang:profileFor(id).language}));try{sessionStorage.setItem('dawa-next-active',id);}catch{}await refreshPhotos();render();startQueue();}
async function resetPatient(){const id=activeId;closeDialog();try{await clearPatientPhotos(id);}catch{toast(t('Local photo storage is unavailable.'));return;}store(enableInitialReminders(newPatient(id)));ask={medId:'',text:'',sampleId:null,result:null};await refreshPhotos();view='now';careView=false;render();toast(t('Reset complete.'));}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){event.preventDefault();if(activeId){closeDialog();view='now';careView=false;render();}return;}if(b.dataset.login){await login(b.dataset.login);return;}if(!p())return;
 const action=b.dataset.action;if(careView&&!['patient','read-alerts','close','stop-audio','accessibility'].includes(action)&&!b.dataset.source&&!b.dataset.listen)return;
 if(b.dataset.view){closeDialog();cancelRecording();view=b.dataset.view;render();window.scrollTo(0,0);return;}
 if(b.dataset.subview){subview=b.dataset.subview;render();return;}
 if(b.dataset.dose){openDose(b.dataset.dose);return;}
 if(b.dataset.med){showMed(b.dataset.med);return;}
 if(b.dataset.listen){const m=p().meds.find(m=>m.id===b.dataset.listen);if(m)playMedicine(m,lang()).catch(()=>toast(t('Voice could not play. Please tap Listen again.')));return;}
 if(b.dataset.removeFood){store(removeFoodChoice(p(),b.dataset.removeFood));$('#food-results').innerHTML=foodListResults();toast(t('Food removed.'));return;}
 if(b.dataset.checkFood){openFoodCheck(b.dataset.checkFood);return;}
 if(b.dataset.askSample){const s=SAMPLE_QUESTIONS.find(s=>s.id===b.dataset.askSample);if(s)runAsk(s.en,s.medId,s.id);return;}
 if(b.dataset.source){showSource(b.dataset.source);return;}
 if(b.dataset.clock){store(setClock(p(),b.dataset.clock));closeDialog();render();return;}
 if(b.dataset.ehrAction){store(applyEhrChange(p(),b.dataset.ehrAction));closeDialog();render();toast(t('Saved'));return;}
 if(b.dataset.removeSupplement){store({...p(),supplements:p().supplements.filter(item=>item.id!==b.dataset.removeSupplement)});render();return;}
 if(b.dataset.deletePhoto){await removeReviewPhoto(b.dataset.deletePhoto,activeId);await refreshPhotos();render();toast(t('Photo removed.'));return;}
 if(b.dataset.writeTag){writeTag(b.dataset.writeTag);return;}
if(b.dataset.copyTag){const m=p().meds.find(m=>m.id===b.dataset.copyTag);if(m){try{await navigator.clipboard.writeText(nfcTagFor(p(),m));toast(t('Tag text copied.'));}catch{toast(t('Copy failed. Select the text and copy it yourself.'));}}return;}
if(b.dataset.saveSupply){try{store(saveSupply(p(),'patient',b.dataset.saveSupply,{refillAt:$('#refill-threshold').value,expiresOn:$('#package-expiry').value,remind:true}));closeDialog();render();toast(t('Reminder saved.'));}catch(error){toast(t(error.message));}return;}
 switch(action){
 case 'add-food':{const result=addFoodChoice(p(),$('#food-choice').value);if(result.duplicate){toast(t('Food has already been added'));break;}store(result.state);$('#food-results').innerHTML=foodListResults();toast(t('Food added.'));break;}
 case 'ask-submit':runAsk($('#ask-text').value,$('#ask-med').value,null);break;
 case 'close':closeDialog();break;
 case 'start':startQueue();break;
 case 'schedule':showSchedule();break;
 case 'clock':showClock();break;
 case 'save-clock':store(setClock(p(),$('#demo-clock').value));closeDialog();render();break;
 case 'sample-ocr':{const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(row)scanBottle(new URL('./samples/'+row.med.id+'.png',import.meta.url).href,true);break;}
 case 'wrong-ocr':{const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(row)scanBottle(new URL('./samples/'+(row.med.id==='metformin'?'metformin-wrong-strength':'metformin')+'.png',import.meta.url).href,true);break;}
 case 'nfc':scanNfc();break;
case 'nfc-cancel':nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;scanVersion++;renderDose();break;
 case 'demo-tag':{const row=doseRows(p()).find(r=>r.key===activeDoseKey);if(row)tagResult(nfcTagFor(p(),row.med),'demo-nfc');break;}
 case 'wrong-tag':{const row=doseRows(p()).find(r=>r.key===activeDoseKey),other=row&&p().meds.find(m=>m.id!==row.med.id);if(row)tagResult(other?nfcTagFor(p(),other):'dawa-demo:v1:wrong:wrong:wrong','demo-nfc');break;}
 case 'record-dose':{const result=logTaken(p(),activeDoseKey);if(result.error){toast(t(result.error));break;}store(result.state);afterDose();break;}
 case 'skip-dose':store(skipDose(p(),activeDoseKey));afterDose('skipped');break;

 case 'accessibility':showAccess();break;
 case 'stop-audio':stopVoice();break;
 case 'save-caregiver':{const next=addCaregiver(p(),{name:$('#caregiver-name').value,language:$('#caregiver-lang').value,notify:$('#caregiver-notify').checked});if(next===p()){toast(t('Enter a caregiver name first.'));break;}store(next);render();toast(t('Caregiver saved.'));break;}
 case 'remove-caregiver':store(removeCaregiver(p()));render();toast(t('Caregiver removed.'));break;
 case 'caregiver':if(!p().caregiver){toast(t('No caregiver added'));break;}closeDialog();store(syncMissed(p()));careView=true;render();window.scrollTo(0,0);break;
 case 'patient':careView=false;view='me';render();break;
 case 'read-alerts':store({...p(),alerts:p().alerts.map(a=>({...a,read:true}))});render();break;
 case 'add-supplement':{const next=addSupplement(p(),'patient',{name:$('#supplement-name').value,ingredients:$('#supplement-ingredients').value,stage:'considering',use:''});if(next===p()){toast(t('Please add a product name.'));break;}store(next);render();break;}
 case 'ehr':showEhr();break;
 case 'export':{const blob=new Blob([JSON.stringify(ehrBundle(p()),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dawa-'+activeId+'-synthetic-ehr.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
 case 'reset':showDialog(`<h2>${t('Reset this patient’s sample data?')}</h2><p>${t('This clears this patient’s doses, meal edits, caregiver alerts and uploaded photos.')}</p><button class="primary full" data-action="confirm-reset">${t('Reset patient')}</button>`,'reset');break;
 case 'confirm-reset':await resetPatient();break;
 case 'logout':closeDialog();ask={medId:'',text:'',sampleId:null,result:null};activeId=null;careView=false;view='now';photoRecords=[];for(const url of photoUrls)URL.revokeObjectURL(url);photoUrls=[];try{sessionStorage.removeItem('dawa-next-active');}catch{}render();window.scrollTo(0,0);break;
 }
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='language'){if(!p())loginLanguage=el.value;else if(careView&&p().caregiver)store({...p(),caregiver:{...p().caregiver,language:el.value}});else store({...p(),patientLang:el.value});if($('#dialog').open)closeDialog();render();return;}if(!p()||careView&&el.id!=='text-size'&&el.id!=='speech-rate'&&!el.dataset.access)return;
 if(el.id==='ask-med'){ask={...ask,medId:el.value,sampleId:null,result:null};$('#ask-answer').innerHTML='';return;}
 if(el.id==='require-bottle'){store({...p(),requireBottle:el.checked});render();}
 if(el.id==='use-labs')store({...p(),useEhrHealth:el.checked});
 if(el.id==='avoid-pork')store({...p(),avoidPork:el.checked});
 if(el.id==='live-clock'){store(syncMissed({...p(),liveClock:el.checked}));closeDialog();render();}
 if(el.id==='text-size'){store({...p(),accessibility:{...p().accessibility,textSize:el.value}});document.body.dataset.textSize=el.value;}
 if(el.id==='speech-rate'){store({...p(),accessibility:{...p().accessibility,speechRate:setVoiceRate(el.value)}});}
 if(el.dataset.access){store({...p(),accessibility:{...p().accessibility,[el.dataset.access]:el.checked}});document.body.dataset.contrast=p().accessibility.highContrast?'high':'normal';document.body.dataset.motion=p().accessibility.reduceMotion?'reduce':'normal';}
 if(el.dataset.reminder)store({...p(),reminders:{...p().reminders,doses:{...p().reminders.doses,[el.dataset.reminder]:{enabled:el.checked}}}});
 if(el.id==='bottle-photo'&&el.files?.[0])scanBottle(el.files[0]);
 if(el.id==='new-photo'&&el.files?.[0])addPhoto(el.files[0]);
});
document.addEventListener('input',event=>{if(event.target.id==='ask-text')ask.text=event.target.value;});
document.addEventListener('keydown',event=>{if(event.target.id==='ask-text'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();runAsk(event.target.value,$('#ask-med').value,null);}});
$('#dialog').addEventListener('cancel',()=>{scanVersion++;scanBusy=false;nfcAbort?.abort();nfcAbort=null;nfcWaiting=false;nfcNote='';writeAbort?.abort();writeAbort=null;cancelRecording();stopVoice();dialogType='';activeDoseKey='';queueKeys=[];});
window.addEventListener('storage',event=>{if(!activeId||event.key!==patientSourceKey(activeId))return;try{states.set(activeId,restorePatient(JSON.parse(event.newValue),activeId));closeDialog();render();}catch{}});
setInterval(()=>{if(!p())return;const next=syncMissed(p());if(next!==p()){store(next);if(!$('#dialog').open)render();}if(p().liveClock){if(dialogType==='dose')renderDose();else if(!$('#dialog').open){render();if(!careView&&dueRows(p()).length)startQueue();}}},20000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(activeId){store(syncMissed(p()));await refreshPhotos();}render();
await handleTagLink();window.addEventListener('hashchange',()=>{handleTagLink();});

function foodCheckFor(entry){return evaluateFoodChoice(p(),entry);}
function foodListResults(){const results=selectedFoods(p());return results.length?results.map(entry=>{const check=foodCheckFor(entry),label=local(entry);return `<div class="food-option-row"><button class="food-result ${check.level}" data-check-food="${entry.id}"><span class="status-dot" aria-hidden="true"></span><span><b>${esc(label)}</b><small>${t(check.label||{green:'Checked instruction',yellow:'Check first',red:'Avoid warning',unknown:'Ingredient review'}[check.level])}</small>${check.sampleRecipe?`<span class="sample-ingredients"><b>${t('Sample recipe')}:</b> ${t(check.ingredients)}</span><span class="sample-scope">${t(check.scope)}</span>`:''}</span>${icon('arrow')}</button><button class="remove-food" data-remove-food="${entry.id}" aria-label="${esc(t('Remove')+' · '+label)}">${icon('close')}<span>${t('Remove')}</span></button></div>`;}).join(''):`<p class="note">${t('No foods added yet.')}</p>`;}
function openFoodCheck(id){const entry=selectedFoods(p()).find(e=>e.id===id)||foodChoices(activeId).find(e=>e.id===id);if(!entry)return;const check=foodCheckFor(entry);showDialog(`<span class="badge ${check.level}">${t(check.label||{green:'Checked instruction',yellow:'Check first',red:'Avoid warning',unknown:'Ingredient review'}[check.level])}</span><h2>${esc(local(entry))}</h2>${check.sampleRecipe?`<p class="note"><b>${t('Sample recipe')}:</b> ${t(check.ingredients)}</p>`:''}<p>${check.level==='unknown'?t('Recipes vary. Ask your pharmacist to review the ingredients with your medicines.'):t(check.text)}</p>${check.source?sourceButton(check.source):''}<p class="note">${t('Green applies only to the named check. Recipes may need ingredient review.')}</p>`,'food');}

function askMedId(){return ask.medId&&p().meds.some(m=>m.id===ask.medId)?ask.medId:p().meds[0].id;}
function askView(){const medId=askMedId();return `<section class="card ask-card"><h2>${t('Ask about this medicine')}</h2><label for="ask-med">${t('About this medicine')}</label><select id="ask-med">${p().meds.map(m=>`<option value="${m.id}" ${m.id===medId?'selected':''}>${esc(name(m))} · ${esc(strength(m))}</option>`).join('')}</select><label for="ask-text">${t('Your question')}</label><textarea id="ask-text" rows="3" maxlength="200" placeholder="${esc(t('Type a question about this medicine'))}">${esc(ask.text)}</textarea><button class="primary full" data-action="ask-submit">${icon('ask')}${t('Ask Dawa')}</button></section><section class="ask-samples" aria-label="${esc(t('Try a sample question'))}"><h3 class="section-heading">${t('Try a sample question')}</h3>${SAMPLE_QUESTIONS.map(s=>{const m=p().meds.find(m=>m.id===s.medId);return `<button class="sample-question" data-ask-sample="${s.id}"><span><b>${esc(local(s))}</b>${m?`<small>${esc(name(m))} · ${esc(strength(m))}</small>`:''}</span>${icon('arrow')}</button>`;}).join('')}</section><div id="ask-answer" aria-live="polite">${askAnswerHtml()}</div><p class="note">${t('Answers come from reviewed medicine guides built into this demo. Dawa is not a live medical advisor.')}</p>`;}
function askAnswerHtml(){const r=ask.result;if(!r)return '';const m=p().meds.find(m=>m.id===r.medId),sample=ask.sampleId&&SAMPLE_QUESTIONS.find(s=>s.id===ask.sampleId),question=sample?local(sample):r.question,badge={red:['red','Avoid warning'],yellow:['yellow','Check first'],grey:['','Ask your pharmacist'],urgent:['red','Urgent']},allSources={...SOURCES,...FOOD_CHECK_SOURCES,...ASK_SOURCES};
 return `<div class="ask-q"><small>${t('You asked')}${m?` · ${esc(name(m))} ${esc(strength(m))}`:''}</small><p>${esc(question)}</p></div>${r.items.map(i=>`<article class="ask-item ${i.level}"><div class="ask-head"><b>${t('Dawa answers')}</b><span class="badge ${badge[i.level][0]}">${t(badge[i.level][1])}</span></div><h3>${t(i.title)}</h3><p>${t(i.text)}</p>${i.steps?.length?`<ul>${i.steps.map(step=>`<li>${t(step)}</li>`).join('')}</ul>`:''}${(i.sources||[]).filter(key=>allSources[key]).map(key=>`<button class="source-button" data-source="${key}">${esc(allSources[key].title)} ↗</button>`).join('')}</article>`).join('')}`;}
function runAsk(text,medId,sampleId){const sample=sampleId&&SAMPLE_QUESTIONS.find(s=>s.id===sampleId),result=askDawa({medId,text:sample?sample.en:text,meds:p().meds});if(result.error){toast(t(result.error));return;}ask={medId:result.medId,text:sample?local(sample):text,sampleId:sample?sample.id:null,result};$('#ask-med').value=ask.medId;$('#ask-text').value=ask.text;$('#ask-answer').innerHTML=askAnswerHtml();$('#ask-answer').scrollIntoView({behavior:p().accessibility.reduceMotion?'auto':'smooth',block:'start'});}
